import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {chromium} from '@playwright/test';import {createBrowserGame as createGameServer} from './browser-game-server.mjs';
const dir='evidence/audit-20261026',g=await createGameServer({dataDir:fs.mkdtempSync(path.join(os.tmpdir(),'kc5-visual-audit-'))}),r=g.room,s=r.sim;r.paused=true;
await new Promise(resolve=>g.server.listen(0,'127.0.0.1',resolve));const browser=await chromium.launch({headless:true,executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe'}),page=await browser.newPage({viewport:{width:1440,height:1200}}),out={errors:[],states:[]};page.on('pageerror',e=>out.errors.push(e.message));
try{await page.goto(`http://127.0.0.1:${g.server.address().port}`);await page.locator('#accountName').fill('炮击视觉检测');await page.locator('#accountPassword').fill('isolated-visual-audit');await page.locator('#authSubmit').click();await page.waitForFunction(()=>window.__game?.renderer.getCamera());const p=r.player(g.accounts.rows[0]);p.classId=2;p.level=6;p.builds[2]=[1,1,1,1];const u=s.units.find(u=>u.type==='siege');s.contract(p,u.id);s.units=s.units.filter(x=>x.id===u.id);Object.assign(u,{x:0,y:0,speed:0,cd:1e9});const e=s.spawn(1,'melee',0,1,0);Object.assign(e,{x:0,y:3,speed:0,cd:1e9,hp:1e7,maxHp:1e7});for(const t of s.towers)t.x=100;s.waveAt=1e9;
const sync=async()=>{r.sequence++;r.broadcast();await page.waitForFunction(q=>__game.sim.sequence>=q,r.sequence);await page.waitForTimeout(50);};const advance=n=>{const end=s.time+n;while(s.time<end-1e-8)s.tick(Math.min(.05,end-s.time));};
await sync();await page.locator('#locate').click();await page.waitForTimeout(350);await page.locator('[data-cast="2"]').click();await page.waitForFunction(()=>__game.sim.player.cd[2]>__game.sim.time);
for(const [at,name]of [[.4,'barrage-start'],[1.15,'barrage-first-impact'],[1.74,'barrage-gap'],[3.4,'barrage-final']]){advance(at-s.time);await sync();const visual=await page.evaluate(()=>{const scene=__game.renderer.game.scene.scenes[0];return {time:__game.sim.time,channelUntil:__game.sim.hero().channelUntil,fieldKinds:__game.sim.fields.map(f=>f.kind),visualReport:JSON.parse(JSON.stringify(scene.skillFX.report))};});out.states.push({at,name,visual,slow:s.activeDebuffs(e,'moveSlow').map(x=>({ratio:x.ratio,stacks:x.stacks,until:x.until})),value:s.skillValues.at(-1)?structuredClone(s.skillValues.at(-1)):null,targetHp:e.hp});await page.screenshot({path:`${dir}/${name}.png`});}
}catch(e){out.fatal=e.stack;}finally{fs.writeFileSync(`${dir}/visual-audit.json`,JSON.stringify(out,null,2));await browser.close();for(const c of [...r.clients])c.res.end();g.server.closeAllConnections();await new Promise(resolve=>g.server.close(resolve));console.log(JSON.stringify(out,null,2));}
